function el(tag, cls, text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node}
function card(a){const link=el("a","article-card");link.href=`article.html?id=${encodeURIComponent(a.id)}`;link.append(el("p","eyebrow",a.category.toUpperCase()+" · "+a.language));link.append(el("h3","",a.title));link.append(el("p","",a.excerpt));link.append(el("span","article-date",a.date+"  ↗"));return link}
function renderCards(target, list){if(!target)return;target.replaceChildren();if(!list.length){target.append(el("p","empty-state","No articles match your search yet."));return}list.forEach(a=>target.append(card(a)))}
renderCards(document.querySelector("#latest-articles"),articles.slice(0,2));
const all=document.querySelector("#all-articles");renderCards(all,articles);
const search=document.querySelector("#search"),category=document.querySelector("#category");
function filter(){if(!all)return;const q=(search?.value||"").toLowerCase();const c=category?.value||"all";renderCards(all,articles.filter(a=>(c==="all"||a.category===c)&&[a.title,a.excerpt,a.category].join(" ").toLowerCase().includes(q)))}
search?.addEventListener("input",filter);category?.addEventListener("change",filter);
const content=document.querySelector("#article-content");
if(content){const id=new URLSearchParams(location.search).get("id");const a=articles.find(x=>x.id===id);
 if(!a){content.replaceChildren(el("p","eyebrow","ARTICLE NOT FOUND"));content.append(el("h1","","This page is still waiting for its article."));const back=el("a","text-link","Browse all articles ↗");back.href="articles.html";content.append(back)}
 else{
  document.title=a.title+" — Sufyan Khan Sadozai";
  content.replaceChildren();
  const back=el("p","eyebrow");const backLink=el("a","","← ALL ARTICLES");backLink.href="articles.html";back.append(backLink);content.append(back);
  content.append(el("h1","",a.title));content.append(el("p","article-deck",a.excerpt));content.append(el("p","article-byline","BY SUFYAN KHAN SADOZAI  ·  "+a.date+"  ·  "+a.category.toUpperCase()));
  const switcher=el("div","language-switch");const enBtn=el("button","selected","English");const urBtn=el("button","","اردو");enBtn.type=urBtn.type="button";switcher.append(enBtn,urBtn);content.append(switcher);
  const body=el("div","prose");content.append(body);
  function show(lang){body.replaceChildren();body.className=lang==="ur"?"prose urdu article-urdu":"prose";body.lang=lang;body.dir=lang==="ur"?"rtl":"ltr";a[lang].forEach(([type,txt])=>{const tag=type==="quote"?"blockquote":type==="h2"?"h2":"p";body.append(el(tag,"",txt))});enBtn.classList.toggle("selected",lang==="en");urBtn.classList.toggle("selected",lang==="ur")}
  enBtn.addEventListener("click",()=>show("en"));urBtn.addEventListener("click",()=>show("ur"));show("en");
 }
}
document.querySelectorAll("[data-year]").forEach(n=>n.textContent=new Date().getFullYear());
const menu=document.querySelector(".menu-toggle"),nav=document.querySelector(".site-header nav");
menu?.addEventListener("click",()=>{const open=nav.classList.toggle("open");menu.setAttribute("aria-expanded",String(open))});
